#include <iostream>
#include <numeric>
using namespace std;

long long get_gcd(long long a, long long b) {
    while (b != 0) {
        long long temp = a % b;
        a = b;
        b = temp;
    }
    return a;
}

struct Fraction {
    long long num, den;
    Fraction() : num(0), den(1) {}
    Fraction(long long n, long long d) : num(n), den(d) {}
    void reduce() {
        long long g = get_gcd(num, den);
        num /= g;
        den /= g;
    }
    bool operator<(const Fraction& other) const {
        return num * other.den < other.num * den;
    }
    void print() const {
        cout << num << "/" << den;
    }
};

int main() {
    long long x, y, n;
    cin >> x >> y >> n;
    Fraction limit(50, 1);
    Fraction base(x, y);
    long long best_r = 0, best_i = 1;
    for (long long i = 1; i <= n; ++i) {
        long long r = (base.num * i) / base.den;
        long long z = (base.num * i) % base.den;
        if (z > base.den / 2) {
            r++;
            z = base.den - z;
        }
        Fraction current(z, i * base.den);
        if (current < limit) {
            limit = current;
            best_r = r;
            best_i = i;
        }
    }
    cout << best_r;
}
